PRAGMA foreign_keys = ON;
CREATE TABLE libraries (id TEXT PRIMARY KEY, created_at INTEGER NOT NULL);
CREATE TABLE categories (id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id), name TEXT NOT NULL, parent_id TEXT, created_at INTEGER NOT NULL, UNIQUE(library_id, id), UNIQUE(library_id, name), FOREIGN KEY(library_id, parent_id) REFERENCES categories(library_id, id));
CREATE TABLE tags (id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id), name TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(library_id, id), UNIQUE(library_id, name));
CREATE TABLE blobs (id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id), object_key TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, size INTEGER NOT NULL CHECK(size > 0), mime TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(library_id,id), UNIQUE(library_id,sha256,size));
CREATE TABLE assets (id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id), blob_id TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', favorite INTEGER NOT NULL DEFAULT 0 CHECK(favorite IN (0,1)), category_id TEXT, source_id TEXT, source_url TEXT, media_id TEXT, poster_key TEXT, duration REAL, width INTEGER, height INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(library_id,id), UNIQUE(library_id,source_id,media_id), FOREIGN KEY(library_id,blob_id) REFERENCES blobs(library_id,id), FOREIGN KEY(library_id,category_id) REFERENCES categories(library_id,id));
CREATE INDEX assets_library_created ON assets(library_id,created_at DESC,id);
CREATE TABLE asset_tags (library_id TEXT NOT NULL, asset_id TEXT NOT NULL, tag_id TEXT NOT NULL, PRIMARY KEY(asset_id,tag_id), FOREIGN KEY(library_id,asset_id) REFERENCES assets(library_id,id) ON DELETE CASCADE, FOREIGN KEY(library_id,tag_id) REFERENCES tags(library_id,id) ON DELETE CASCADE);
CREATE TABLE devices (id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id), name TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, scopes TEXT NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER, last_seen_at INTEGER, cursor TEXT, created_at INTEGER NOT NULL, UNIQUE(library_id,id));
CREATE TABLE pairings (id TEXT PRIMARY KEY, device_code_hash TEXT NOT NULL UNIQUE, user_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, requested_scopes TEXT NOT NULL, approved_scopes TEXT, library_id TEXT REFERENCES libraries(id), state TEXT NOT NULL CHECK(state IN ('pending','approved','consumed','denied')), expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE uploads (id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id), device_id TEXT, object_key TEXT NOT NULL UNIQUE, multipart_id TEXT NOT NULL, input TEXT NOT NULL, size INTEGER NOT NULL, sha256 TEXT NOT NULL, mime TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('uploading','completing','verifying','ready','failed','cancelled')), asset_id TEXT, error_code TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, FOREIGN KEY(library_id,device_id) REFERENCES devices(library_id,id));
CREATE INDEX uploads_library_hash ON uploads(library_id,sha256,size,status);
CREATE TABLE upload_parts (upload_id TEXT NOT NULL REFERENCES uploads(id) ON DELETE CASCADE, part_number INTEGER NOT NULL, etag TEXT NOT NULL, size INTEGER NOT NULL, sha256 TEXT NOT NULL, PRIMARY KEY(upload_id,part_number));
CREATE TABLE jobs (id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id), source_url TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','claimed','ready','failed','cancelled')), device_id TEXT, lease_until INTEGER, asset_id TEXT, error_code TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, FOREIGN KEY(library_id,device_id) REFERENCES devices(library_id,id));
CREATE TABLE imports (id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id), device_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('fetching','ready','failed')), asset_id TEXT, error_code TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(library_id,device_id,idempotency_key));
CREATE TABLE audit (id TEXT PRIMARY KEY, library_id TEXT, device_id TEXT, action TEXT NOT NULL, target_id TEXT, created_at INTEGER NOT NULL);
CREATE INDEX audit_library_time ON audit(library_id,created_at DESC);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, window INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE TABLE garbage (object_key TEXT PRIMARY KEY, delete_after INTEGER NOT NULL);
